description:
{
  "image_category": "MARKING_AND_SIGNAL",
  "summary": "Hình ảnh minh họa bố trí các loại vạch kẻ đường (dừng xe, chỉ hướng, phân làn, vạch đi bộ) tại nút giao thông có đèn tín hiệu, kèm chú thích tên từng loại vạch.",
  "items": [
    {
      "identifier": "Vạch dừng xe",
      "visual_or_geometric_features": "Vạch liền nét màu trắng, kẻ ngang toàn bộ bề rộng đường tại vị trí dừng xe chờ tín hiệu đèn.",
      "meaning_or_specification": "Dùng để xác định vị trí dừng xe khi có tín hiệu đèn đỏ hoặc biển R.122; bề rộng vạch 20–40 cm tùy cấp đường."
    },
    {
      "identifier": "Vạch chỉ hướng",
      "visual_or_geometric_features": "Vạch liền nét màu trắng, kẻ dọc theo làn xe để chỉ hướng di chuyển của phương tiện.",
      "meaning_or_specification": "Chỉ dẫn cho người lái xe biết hướng di chuyển được phép trong làn xe tương ứng."
    },
    {
      "identifier": "Vạch phân làn xe",
      "visual_or_geometric_features": "Vạch liền nét màu vàng, kẻ dọc giữa các làn xe cùng chiều hoặc ngược chiều.",
      "meaning_or_specification": "Phân chia các làn xe chạy, thường dùng để phân làn xe cơ giới và xe thô sơ hoặc phân làn theo hướng di chuyển."
    },
    {
      "identifier": "Vạch phân làn cắt góc",
      "visual_or_geometric_features": "Vạch liền nét màu vàng, kẻ chéo tại góc nút giao để phân định khu vực cấm hoặc ranh giới làn xe.",
      "meaning_or_specification": "Dùng để phân định khu vực cấm xe hoặc ranh giới làn xe tại nút giao, đặc biệt là khu vực cấm xe thô sơ hoặc làn chờ rẽ trái."
    },
    {
      "identifier": "Đèn tín hiệu",
      "visual_or_geometric_features": "Cột đèn tín hiệu giao thông đặt tại nút giao, có các đèn đỏ, vàng, xanh.",
      "meaning_or_specification": "Điều khiển luồng giao thông tại nút giao, yêu cầu phương tiện dừng lại khi đèn đỏ hoặc nhường đường khi đèn vàng."
    }
  ]
}
